package main

import (
	"bytes"
	_ "embed"
	"os"
	"path/filepath"
)

//go:embed haproxy-resource-entrypoint.sh
var haproxyResourceEntrypoint []byte

func writeHAProxyResourceEntrypoint(dir string, rewrite bool) error {
	path := filepath.Join(dir, "haproxy-resource-entrypoint.sh")
	if !rewrite {
		if body, err := os.ReadFile(path); err == nil {
			// os.WriteFile's mode is masked by the caller's umask. A secure
			// installer invocation with umask 077 left this public launcher
			// at 0700, so non-root HAProxy could not read its bind mount.
			// Repair only our exact generated bytes; never expose an
			// operator-replaced script by silently changing its mode.
			if bytes.Equal(body, haproxyResourceEntrypoint) {
				return os.Chmod(path, 0o755)
			}
			return nil
		} else if !os.IsNotExist(err) {
			return err
		}
	}
	if err := os.WriteFile(path, haproxyResourceEntrypoint, 0o755); err != nil {
		return err
	}
	return os.Chmod(path, 0o755)
}
